<section class="roster">
  <header class="roster__header">
    <div class="roster__intro">
      <h1 hlmH1>Roster</h1>
      <p hlmMuted>Every hero on the books. Example data, not real records.</p>
    </div>
    <a hlmBtn routerLink="/recruit">
      <ng-icon hlmIcon name="lucideUserPlus" />
      Recruit
    </a>
  </header>

  <div class="roster__filters">
    <label hlmLabel for="roster-search" class="roster__label">Search heroes</label>
    <input
      hlmInput
      id="roster-search"
      type="search"
      class="roster__search"
      placeholder="Search by codename or alias"
      [value]="vm.search()"
      (input)="vm.setSearch(search.value)"
      #search
    />

    <label hlmLabel for="roster-class-filter" class="roster__label">Power class</label>
    <hlm-select [value]="vm.classFilter()" (valueChange)="vm.setClassFilter($event)">
      <hlm-select-trigger class="roster__class" buttonId="roster-class-filter">
        <hlm-select-value placeholder="All classes" />
      </hlm-select-trigger>
      <hlm-select-content *hlmSelectPortal>
        @for (option of vm.classOptions; track option.value) {
          <hlm-select-item [value]="option.value">{{ option.label }}</hlm-select-item>
        }
      </hlm-select-content>
    </hlm-select>
  </div>

  <div hlmTableContainer class="roster__table">
    <table hlmTable aria-label="Hero roster">
      <thead hlmTHead>
        <tr hlmTr>
          <th hlmTh scope="col">Hero</th>
          <th hlmTh scope="col">Class</th>
          <th hlmTh scope="col">Power</th>
          <th hlmTh scope="col">Status</th>
          <th hlmTh scope="col">Clearance</th>
          <th hlmTh scope="col">Actions</th>
        </tr>
      </thead>
      <tbody hlmTBody>
        @for (row of vm.rows(); track row.id) {
          <tr hlmTr>
            <td hlmTd>
              <div class="roster__hero">
                <hlm-avatar aria-hidden="true">
                  <span hlmAvatarFallback>{{ row.initials }}</span>
                </hlm-avatar>
                <div class="roster__identity">
                  <a [routerLink]="['/detail', row.id]">{{ row.name }}</a>
                  <span hlmMuted>{{ row.code }}</span>
                </div>
              </div>
            </td>
            <td hlmTd><span hlmBadge variant="outline">{{ row.powerClass }}</span></td>
            <td hlmTd>{{ row.power }}</td>
            <td hlmTd><span hlmBadge [variant]="row.statusVariant">{{ row.status }}</span></td>
            <td hlmTd>{{ row.clearance }}</td>
            <td hlmTd>
              <div class="roster__actions">
                <a
                  hlmBtn
                  variant="ghost"
                  size="icon"
                  [routerLink]="['/detail', row.id]"
                  [attr.aria-label]="'Edit ' + row.name"
                  [hlmTooltip]="'Edit ' + row.name"
                >
                  <ng-icon hlmIcon name="lucidePencil" />
                </a>
                <a
                  hlmBtn
                  variant="ghost"
                  size="icon"
                  [routerLink]="['/detail', row.id]"
                  [attr.aria-label]="'Retire ' + row.name"
                  [hlmTooltip]="'Retire ' + row.name"
                >
                  <ng-icon hlmIcon name="lucideTrash2" />
                </a>
              </div>
            </td>
          </tr>
        } @empty {
          <tr hlmTr>
            <td hlmTd colspan="6" class="roster__empty">
              <p hlmMuted>No heroes match these filters.</p>
            </td>
          </tr>
        }
      </tbody>
      <tfoot hlmTFoot>
        <tr hlmTr>
          <td hlmTd colspan="6">
            <div class="roster__summary">
              <span>{{ vm.matched() }} of {{ vm.total() }} heroes</span>
              <span hlmMuted>sorted by power</span>
            </div>
          </td>
        </tr>
      </tfoot>
    </table>
  </div>
</section>

