import { Component, computed, input } from '@angular/core';
import { HlmTypographyImports } from '@spartan-ng/helm/typography';

// Presentational: a 0-100 power index. Clamps out-of-range input so a bad record cannot misreport.
@Component({
  selector: 'app-power-meter',
  imports: [HlmTypographyImports],
  templateUrl: './power-meter.html',
  styleUrl: './power-meter.css',
})
export class PowerMeter {
  readonly value = input.required<number>();
  readonly label = input('Power index');
  protected readonly clamped = computed(() => Math.min(100, Math.max(0, Math.round(this.value()))));
}
<div class="power-meter">
  <span hlmMuted>{{ label() }}</span>
  <p hlmLarge class="power-meter__value">{{ clamped() }}<span hlmMuted> / 100</span></p>
</div>
import { NgIcon, provideIcons } from '@ng-icons/core';
import { lucideActivity, lucideShieldAlert, lucideUserCheck, lucideZap } from '@ng-icons/lucide';
import { HlmCardImports } from '@spartan-ng/helm/card';
import { HlmIconImports } from '@spartan-ng/helm/icon';
import { HlmTypographyImports } from '@spartan-ng/helm/typography';
import { Component, input } from '@angular/core';

export type StatIcon = 'lucideUserCheck' | 'lucideActivity' | 'lucideZap' | 'lucideShieldAlert';

// Presentational: a figure and its caption. Injects nothing; the ViewModel supplies the numbers.
@Component({
  selector: 'app-stat-tile',
  imports: [NgIcon, HlmIconImports, HlmCardImports, HlmTypographyImports],
  providers: [provideIcons({ lucideActivity, lucideShieldAlert, lucideUserCheck, lucideZap })],
  templateUrl: './stat-tile.html',
  styleUrl: './stat-tile.css',
})
export class StatTile {
  readonly label = input.required<string>();
  readonly value = input.required<number | string>();
  readonly hint = input<string>('');
  readonly icon = input.required<StatIcon>();
}
<article hlmCard class="stat-tile">
  <div hlmCardHeader class="stat-tile__header">
    <p hlmCardDescription>{{ label() }}</p>
    <ng-icon hlmIcon [name]="icon()" tone="primary" />
  </div>
  <div hlmCardContent class="stat-tile__body">
    <p hlmLarge>{{ value() }}</p>
    <p hlmMuted>{{ hint() }}</p>
  </div>
</article>
