import { Injectable, computed, inject, linkedSignal, signal } from '@angular/core';
import { toSignal } from '@angular/core/rxjs-interop';
import { ActivatedRoute } from '@angular/router';
import type { BadgeVariants } from '@spartan-ng/helm/badge';
import { HeroService } from '../domain/hero.service';
import type { HeroClearance, HeroPowerClass, HeroStatus } from '../domain/hero.model';

export const ALL_CLASSES = 'all';
export type ClassFilter = typeof ALL_CLASSES | HeroPowerClass;

export interface ClassOption {
  readonly value: ClassFilter;
  readonly label: string;
}

export interface RosterRow {
  readonly id: string;
  readonly code: string;
  readonly name: string;
  readonly initials: string;
  readonly powerClass: HeroPowerClass;
  readonly power: number;
  readonly status: HeroStatus;
  readonly statusVariant: BadgeVariants['variant'];
  readonly clearance: HeroClearance;
}

const POWER_CLASSES: readonly HeroPowerClass[] = [
  'Aerial',
  'Energy',
  'Psionic',
  'Tech',
  'Mutant',
  'Cosmic',
  'Enhanced',
];

const STATUS_VARIANT: Readonly<Record<HeroStatus, BadgeVariants['variant']>> = {
  Active: 'success',
  Injured: 'warning',
  Reserve: 'secondary',
  MIA: 'destructive',
};

function initialsOf(name: string): string {
  return name
    .split(/\s+/)
    .filter(Boolean)
    .map((word) => word.charAt(0).toUpperCase())
