import { map } from 'rxjs';
import type { Hero } from '../domain/hero.model';
import { HeroService } from '../domain/hero.service';
import { heroSchema, type HeroModel } from '../domain/hero.schema';
import { formMeta } from '../forms/zod-meta';
import { STATUS_VARIANT, initialsOf } from '../heroes/heroes.view-model';

export const DETAIL_TABS = ['overview', 'powers', 'missions', 'edit'] as const;
export type DetailTab = (typeof DETAIL_TABS)[number];

type ChoiceField = 'powerClass' | 'status' | 'clearance';

const BLANK_MODEL: HeroModel = {
  name: '',
  alias: '',
  powerClass: 'Aerial',
  power: 0,
  status: 'Active',
  clearance: 'Tier 1',
  notes: '',
};

function toModel(hero: Hero | undefined): HeroModel {
  if (!hero) {
    return BLANK_MODEL;
  }
  return {
    name: hero.name,
    alias: hero.alias,
    powerClass: hero.powerClass,
    power: hero.power,
    status: hero.status,
    clearance: hero.clearance,
    notes: hero.notes,
  };
}

// One hero's detail screen: route lookup, the edit form, and the header actions. Component-scoped, no DOM.
@Injectable()
export class HeroDetailViewModel {
  private readonly heroService = inject(HeroService);
  private readonly router = inject(Router);

  // The router reuses this screen when only the id changes, so the id is a signal, not a snapshot read.
  private readonly id = toSignal(
    inject(ActivatedRoute).paramMap.pipe(map((params) => params.get('id') ?? '')),
    { requireSync: true },
  );

  readonly hero = computed(() => this.heroService.byId(this.id()));
  readonly tab = signal<DetailTab>('overview');
  readonly notice = signal('');

  // Labels, control kinds and options all come off the zod schema; nothing here restates them.
  readonly meta = formMeta(heroSchema);

  // Reset to the stored record whenever the hero changes, so a reused screen never shows the last hero's edits.
  private readonly model = linkedSignal<HeroModel>(() => toModel(this.hero()));
  readonly heroForm = form(this.model, (path) => validateStandardSchema(path, heroSchema));

  readonly profile = computed(() => {
    const hero = this.hero();
    if (!hero) {
      return null;
    }
    const wins = Math.round((hero.missions * hero.successRate) / 100);
    return {
      name: hero.name,
      alias: hero.alias,
      code: `HX-${hero.id.padStart(3, '0')}`,
      initials: initialsOf(hero.name),
      powerClass: hero.powerClass,
      power: hero.power,
      status: hero.status,
      statusVariant: STATUS_VARIANT[hero.status],
      clearance: hero.clearance,
      joined: hero.joined,
      notes: hero.notes,
      missions: hero.missions,
      successRate: hero.successRate,
      wins,
      losses: hero.missions - wins,
    };
  });

  readonly canDeploy = computed(() => this.hero()?.status === 'Active');
  readonly isActive = computed(() => this.model().status === 'Active');

  setTab(value: string): void {
    const tab = DETAIL_TABS.find((item) => item === value);
    if (tab) {
      this.tab.set(tab);
    }
  }

  // hlm-select emits its value untyped, so accept only a value the schema allows for that field.
  setChoice<K extends ChoiceField>(field: K, value: unknown): void {
    const parsed = heroSchema.shape[field].safeParse(value);
    if (parsed.success) {
      this.model.update((model) => ({ ...model, [field]: parsed.data }));
    }
  }

  // The switch reads as "on active duty": on maps to Active, off to Reserve.
  setActive(active: boolean): void {
    this.model.update((model) => ({ ...model, status: active ? 'Active' : 'Reserve' }));
  }

  save(): Promise<boolean> {
    const id = this.id();
    return submit(this.heroForm, async () => {
      this.heroService.update(id, this.model());
      this.notice.set(`Saved changes to ${this.model().name}.`);
    });
  }

  cancel(): void {
    this.model.set(toModel(this.hero()));
    this.notice.set('Edits discarded.');
  }

  deploy(): void {
    const hero = this.hero();
    if (hero && this.canDeploy()) {
      this.notice.set(`Deployment order filed for ${hero.name}.`);
    }
  }

  retire(): void {
    const hero = this.hero();
    if (!hero) {
      return;
    }
    this.heroService.remove(hero.id);
    void this.router.navigateByUrl('/roster');
  }
}

